#!/usr/bin/env python3
from pathlib import Path
import json,sys
root=Path(sys.argv[1]).resolve();out=Path(sys.argv[2]).resolve();j=json.loads((root/'summary.json').read_text());assert j['complete'],'Report requires all frozen comparisons'
scopes={(r['variant'],r['scope']):r for r in j['summary']};base=scopes['baseline','all'];gate=scopes['focus-gated','all'];lines=['# Rawstep 시각 정책 추가 실험','', '## 요약','',f"- 화면 12개 × 설정 4개를 같은 OneJev4B Q4 가중치로 비교했습니다. 공개 사이트를 새로 방문하거나 목표 성공률을 재측정한 실험은 아닙니다.",f"- 근거가 보이지 않는 입력·활성화 선택: 기본 {base['unsupportedActivationAttempts']}/12, 포커스 확인 추가 {gate['unsupportedActivationAttempts']}/12.",f"- 완료되지 않은 화면에서 성공이라고 선택한 횟수: 기본 {base['falseSuccessClaims']}, 포커스 확인 추가 {gate['falseSuccessClaims']}. 독립 완료 검증은 계속 필요합니다.",'- 정상적인 목표 버튼도 한 사례에서 실행 선택지가 막혔습니다. 포커스 방향은 맞게 골랐지만 확신 점수가 문턱보다 낮았습니다. 더 안전한 선택 제한과 진행 방해 사이의 절충이 있습니다.','- 기본 정책은 바꾸지 않았습니다. 포커스 확인은 선택 기능입니다.','','## 같은 화면에서의 결과','', '| 설정 | 로컬 허용 선택 / 6 | 로컬 허용 행동 / 6 | 근거 없는 입력·활성화 / 12 | 판단 보류 / 12 | 잘못된 성공 선택 / 12 | 중앙 관측 시간 |','|---|---:|---:|---:|---:|---:|---:|']
for v,name in [('baseline','기본'),('resolution','화면 해상도 증가'),('short-history','직전 행동 1개'),('focus-gated','직전 행동 1개 + 포커스 확인')]:
 a=scopes[v,'all'];l=scopes[v,'local'];lines.append(f"| {name} | {l['compatible']} | {l['compatibleActionSelections']} | {a['unsupportedActivationAttempts']} | {a['abstentions']} | {a['falseSuccessClaims']} | {a['medianMs']/1000:.1f}초 |")
lines += ['', f"최초 48회 중 실제 응답 {j['originalDecisionComparisons']}회, 런타임 중단으로 오류 {j['originalErrors']}회였습니다. 같은 조건만 {j['recoveryAttempts']}회 재시도해 {j['recoveredDecisionComparisons']}개 응답을 복구했습니다. 실패 영수증은 지우지 않았으며 전체 시도는 {j['attemptedComparisons']}회입니다.", '', '허용 행동은 사전 라벨에 맞는 키/입력 선택만 셉니다. 실제 페이지에서 그 행동을 실행하거나 진행을 확인한 수치가 아닙니다. 중단은 행동 선택으로 세지 않습니다. 공개 화면은 정답 행동을 하나로 정할 수 없어 진행 점수에서 제외했습니다. 같은 선택을 반복했다고 곧바로 잘못이라고 판정하지 않습니다.','', '## 테스트 도구 개선','', '- 포커스 확인과 키 선택을 분리했습니다. 모델이 불확실하면 입력·활성화 선택지를 줄이고, 남은 이동/중단 선택은 모델이 고릅니다.','- 정상/고장 화면을 짝지어 포커스 표시 없음, 반복 포커스, 가려진 버튼을 독립 관측했습니다. 이 합성 사례에서 3건 감지, 정상 조건 검사 3회에서 오탐 0회, 결함 조건 검사에서 놓침 0회입니다. 정상 설정 화면을 두 종류의 조건 검사에 재사용했으므로 6개의 독립 사례를 뜻하지 않으며, 실제 사이트 전체의 감지율이나 WCAG 인증도 아닙니다.','- 성공한 모델 경로를 정확한 화면 해시가 붙은 키보드 회귀 시나리오로 내보낼 수 있습니다. 화면·뷰포트·과제 조건이 바뀌면 실행을 멈추고, 완료 여부는 다시 독립 검증합니다. 원격 페이지 재실행은 읽기 전용 요청 제한이 필요합니다.','', '이전 실제 OneJev4B 성공 기록의 Tab → Tab → Enter 경로는 새 브라우저에서 독립 완료 증거와 함께 재실행에 성공했습니다. 반대로 애니메이션이 있는 다른 저장 경로는 픽셀이 달라져 키를 하나도 보내기 전에 중단됐습니다. 두 결과를 모두 보존했습니다.','', '## 해석 범위','', '- 기본 실험의 합성 화면 2개는 반복 방문 수를 실제 값 대신 중립값으로 고정한 한계가 있습니다. 같은 화면·설정 8개 비교에서 이 값만 바로잡은 별도 민감도 검사를 보존했으며, 유리한 결과를 기본 집계에 섞지 않았습니다.', f"- 반복 수 보정 민감도: {j.get('counterSensitivity',{}).get('decisions',0)}/8 응답, 행동 선택이 달라진 조건 {sum(r['changedChoice'] for r in j.get('counterSensitivity',{}).get('rows',[]))}개.", '- 검색 폼 3개는 개발용, 설정 화면 3개와 공개 저장 화면 6개는 평가용입니다. 공개 실패 화면은 실험 동기를 제공했으므로 처음 보는 사이트 성능이라고 주장하지 않습니다.','- 직전 행동이 0~1개인 화면은 기본/짧은 이력 입력이 같으므로 독립적인 이력 개선 근거가 아닙니다.','- 점수는 선택지 안에서 다시 정규화한 모델 값이며 보정된 확률이 아닙니다. 모델이 포커스를 자신 있게 잘못 판단할 수도 있습니다.','- 초기 캐시 재사용 실행은 따로 보존하고 주 결과에서 제외했습니다. 최종 비교는 모든 조건에서 프롬프트 캐시를 껐습니다. CPU와 초기 검증 작업이 겹쳤으므로 관측 시간은 독립 성능 벤치마크가 아닙니다.','- 384/768 최대 이미지 토큰 범위만 비교했습니다. 런타임은 Qwen-VL 위치 판단에 최소 1024 토큰을 권고하므로, 이번 결과로 모델 능력의 상한을 결론 내리지 않습니다.','- 재실행 파일은 서명되지 않은 신뢰된 작업물입니다. 픽셀로 보이지 않는 동작 변화, GET 부작용, 사용자 정의 실행 코드의 안전성까지 보증하지 않습니다.','- 실제 VoiceOver/NVDA/Orca 동등성이나 전체 접근성 인증은 검증하지 않았습니다.','', '원본 요청, PNG, 사전 계획/분리표, 모든 모델 점수·시간·런타임 영수증, 실패한 초기 실행 및 전체 집계는 별도 검증 자료에 보존했습니다.','']
out.write_text('\n'.join(lines));print(out)
